-- Seven authored grade-eight first-term writing exercises; the imported title may contain OCR artifacts.
-- Preserve original title and old synopsis. This is not an official textbook transcription.
WITH qa(sort_order,skill,passage,prompt,correct,w1,w2,w3,practice) AS (VALUES (3,'وصف الشخص: التمهيد','قابلت هدى زميلة تحمل دفترًا أزرق. ساعدت الزميلة طفلًا على العثور على كتاب؛ فاستنتجت هدى أنها متعاونة. لاحظت المعلمة أن لون الدفتر وصف مظهري، بينما المساعدة دليل على الخلق.','أي تصرف يدل على تعاون الزميلة؟','مساعدة الطفل في العثور على كتاب','لون الدفتر الأزرق','الوقوف قرب النافذة','وجود مكتبة','اكتب فقرة تصف هيئة شخص وخلقًا واحدًا يظهر من تصرف محدد.'),
(4,'وصف الشخص: إثراء','ارتدى راشد معطفًا أبيض في المعرض، ثم شرح التجربة ثلاث مرات بهدوء لزملائه. فصلت دانة بين وصف الملبس الذي تدركه العين والحلم الذي يكشف عنه التصرف.','ما الدليل على صبر راشد؟','إعادة الشرح بهدوء','لون معطفه','مكان وقوفه','اسم المعرض','أثر وصف شخص في قصتك بموقف يبرز فضيلة من أفعاله.'),
(5,'وصف الشخص: إنتاج','ساعدت أمينة المكتبة طفلًا على اختيار قصة مناسبة. وصفت مريم نبرة صوت الأمينة ومظهرها، ثم ربطت حسن تعاملها بالمساعدة التي قدمتها.','كيف نُظهر خلقًا حسنًا في وصف شخصية؟','بذكر فعل يدل عليه','بذكر لون الحائط فقط','بتكرار الوصف دون أحداث','بحذف مواقف القصة','أنتج فقرة قصصية تصف شخصية بصفات خَلقية وخُلُقية مع شاهد من الحدث.'),
(6,'تفكيك الموضوع الوصفي','خطط الطلاب لوصف حديقة صباحية؛ سجلوا الأشجار العالية، وزقزقة الطيور، ونسيم الصباح، وشعور الهدوء. صنفوا التفاصيل بحسب الحواس ثم نظموها قبل الكتابة.','أي تفصيل يصف الصوت في الحديقة؟','زقزقة الطيور','لون الأشجار','طول الممر','عدد المقاعد','صمم خريطة لوصف مكان تشمل زمانًا ومشهدين وصوتًا وشعورًا.'),
(7,'وصف الشخص: التخطيط','خططت نورة لقصة متطوع في المكتبة يساعد طفلاً فقد بطاقة الاستعارة. اختارت مشهد المساعدة ليظهر طبع الشخصية قبل كتابة القصة.','ما فائدة مشهد المساعدة في القصة؟','إظهار صفة الشخصية بأفعالها','إلغاء دور الشخصية','إطالة القصة دون هدف','استبدال المشكلة بلون الجدار','اكتب مخططًا لشخصية يشمل المظهر والمشكلة والسلوك والنتيجة.'),
(8,'وصف الشخص: الربط','أعاد سامي كتابًا استعارَه في الموعد المتفق عليه واعتذر عن تأخر سابق. لم يستنتج الكاتب الأمانة من مظهر سامي، بل من تصرفاته.','ما الدليل على أمانة سامي؟','إعادة الكتاب إلى صاحبه','لون حقيبته','طول قامته','مكان جلوسه','اكتب موقفًا قصيرًا يبرز خلقًا من خلال فعل دون التصريح بالصفة.'),
(9,'وصف الشخص: التحرير','حذفت دانة خمس صفات مكررة لشعر البطل وملابسه، وأضافت حوارًا يظهر حسن إصغائه لصديقه. أصبح وصفها أوضح وأقرب إلى حدث القصة.','ما المراجعة الأفضل لوصف الشخصية؟','حذف التكرار وربط الوصف بالحدث','إضافة صفات متكررة','حذف كل الأفعال','إضافة جمل لا صلة لها بالقصة','راجع فقرة وصفية واحذف تكرارًا ثم أضف حدثًا يكشف خُلُق الشخصية.'))
UPDATE public.lessons l SET content=
 'ضاديوم — تمرين كتابة أصلي للصف الثامن الفصل الأول. العنوان المستورد يحتاج مراجعة ملف المصدر وليس نص الكتاب الرسمي.'||E'\n\n'||
 'المهارة: '||qa.skill||E'\n\n'||
 'نموذج داعم أصلي: '||qa.passage||E'\n\n'||
 'سؤال فهم وتحليل: '||qa.prompt||E'\n\n'||
 'مهمة تطبيق: '||qa.practice||E'\n\n'||
 'خطوات الدرس: اقرأ المثال، حدد الدليل على الفكرة، ثم جرّب الصياغة بمفرداتك. راجع علامات الترقيم وتسلسل الحدث ودقة الوصف.'||E'\n\n'||
 'مراعاة الفروق: استخرج مثالًا واحدًا بمساعدة المعلم، ثم اكتب ثلاثة أسطر مستقلة، وللمتقدمين أعد التحرير معللًا الفرق بين النسختين.'||E'\n\n'||
 'التقويم: يتولى المعلم تقييم جودة التعبير؛ إنهاء النشاط الإلكتروني لا يعني اعتماد جودة الكتابة.'||E'\n\n'||
 'الوصف القديم المحفوظ: '||l.content,updated_at=now()
FROM qa JOIN public.units u ON u.semester=1 AND u.title='التعبير والكتابة'
JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=8
JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
WHERE l.unit_id=u.id AND l.sort_order=qa.sort_order AND l.status='published'
AND l.content LIKE 'يتناول هذا الدرس موضوع%' AND length(l.content)<350;
WITH qa(sort_order,skill,passage,prompt,correct,w1,w2,w3,practice) AS (VALUES (3,'وصف الشخص: التمهيد','قابلت هدى زميلة تحمل دفترًا أزرق. ساعدت الزميلة طفلًا على العثور على كتاب؛ فاستنتجت هدى أنها متعاونة. لاحظت المعلمة أن لون الدفتر وصف مظهري، بينما المساعدة دليل على الخلق.','أي تصرف يدل على تعاون الزميلة؟','مساعدة الطفل في العثور على كتاب','لون الدفتر الأزرق','الوقوف قرب النافذة','وجود مكتبة','اكتب فقرة تصف هيئة شخص وخلقًا واحدًا يظهر من تصرف محدد.'),
