(6,'تفكيك الموضوع الوصفي','خطط الطلاب لوصف حديقة صباحية؛ سجلوا الأشجار العالية، وزقزقة الطيور، ونسيم الصباح، وشعور الهدوء. صنفوا التفاصيل بحسب الحواس ثم نظموها قبل الكتابة.','أي تفصيل يصف الصوت في الحديقة؟','زقزقة الطيور','لون الأشجار','طول الممر','عدد المقاعد','صمم خريطة لوصف مكان تشمل زمانًا ومشهدين وصوتًا وشعورًا.'),
(7,'وصف الشخص: التخطيط','خططت نورة لقصة متطوع في المكتبة يساعد طفلاً فقد بطاقة الاستعارة. اختارت مشهد المساعدة ليظهر طبع الشخصية قبل كتابة القصة.','ما فائدة مشهد المساعدة في القصة؟','إظهار صفة الشخصية بأفعالها','إلغاء دور الشخصية','إطالة القصة دون هدف','استبدال المشكلة بلون الجدار','اكتب مخططًا لشخصية يشمل المظهر والمشكلة والسلوك والنتيجة.'),
(8,'وصف الشخص: الربط','أعاد سامي كتابًا استعارَه في الموعد المتفق عليه واعتذر عن تأخر سابق. لم يستنتج الكاتب الأمانة من مظهر سامي، بل من تصرفاته.','ما الدليل على أمانة سامي؟','إعادة الكتاب إلى صاحبه','لون حقيبته','طول قامته','مكان جلوسه','اكتب موقفًا قصيرًا يبرز خلقًا من خلال فعل دون التصريح بالصفة.'),
(9,'وصف الشخص: التحرير','حذفت دانة خمس صفات مكررة لشعر البطل وملابسه، وأضافت حوارًا يظهر حسن إصغائه لصديقه. أصبح وصفها أوضح وأقرب إلى حدث القصة.','ما المراجعة الأفضل لوصف الشخصية؟','حذف التكرار وربط الوصف بالحدث','إضافة صفات متكررة','حذف كل الأفعال','إضافة جمل لا صلة لها بالقصة','راجع فقرة وصفية واحذف تكرارًا ثم أضف حدثًا يكشف خُلُق الشخصية.')), scoped AS
 (SELECT l.id,qa.* FROM qa JOIN public.lessons l ON l.sort_order=qa.sort_order AND l.status='published'
 JOIN public.units u ON l.unit_id=u.id AND u.semester=1 AND u.title='التعبير والكتابة'
 JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=8
 JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
 JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
 WHERE l.content LIKE 'ضاديوم — تمرين كتابة أصلي%' OR (l.content LIKE 'يتناول هذا الدرس موضوع%' AND length(l.content)<350))
INSERT INTO public.lesson_activities(lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
SELECT s.id,'فهم المثال الأصلي','multiple_choice','assessment',s.prompt,
jsonb_build_object('origin','DADYOOM_BH_G8_T1_WRITING_7_SOURCE_CAUTIOUS_20261008','reviewStatus','required','ocrTitleNotVerified',true,'notOfficialBook',true,'options',jsonb_build_array(s.correct,s.w1,s.w2,s.w3)),
jsonb_build_object('correct',s.correct),1,5,true,true FROM scoped s
WHERE NOT EXISTS(SELECT 1 FROM public.lesson_activities a WHERE a.lesson_id=s.id AND a.content->>'origin'='DADYOOM_BH_G8_T1_WRITING_7_SOURCE_CAUTIOUS_20261008' AND a.activity_type='multiple_choice');
