INSERT INTO public.lesson_activities(lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
SELECT s.id,'إنشاء يراجعه المعلم','writing','practice',s.practice,
jsonb_build_object('origin','DADYOOM_BH_G8_T1_WRITING_7_SOURCE_CAUTIOUS_20261008','ocrTitleNotVerified',true,'humanReviewRequired',true,'text',s.practice,'skillQualityAutoVerified',false),
jsonb_build_object('grading_mode','completion_only_reference','model_answer','تتطلب الكتابة مراجعة المعلم للأصالة والدقة والترابط.'),2,5,true,true FROM scoped s
WHERE NOT EXISTS(SELECT 1 FROM public.lesson_activities a WHERE a.lesson_id=s.id AND a.content->>'origin'='DADYOOM_BH_G8_T1_WRITING_7_SOURCE_CAUTIOUS_20261008' AND a.activity_type='writing');